<template>
  <q-dialog :model-value="modelValue" persistent @update:model-value="$emit('update:modelValue', $event)">
    <q-card class="review-dialog">
      <q-toolbar class="toolbar"><q-icon name="rule" color="green-8" size="28px"/><q-toolbar-title>Revisión de diferencias <span>{{ inventario?.codigo }}</span></q-toolbar-title><q-btn flat round dense icon="close" @click="$emit('update:modelValue', false)"/></q-toolbar>
      <q-card-section class="content">
        <q-banner v-if="error" rounded class="bg-red-1 text-negative q-mb-md">{{ error }}</q-banner>
        <div class="summary row q-col-gutter-md q-mb-lg"><div v-for="item in resumen" :key="item.label" class="col-6 col-md-3"><q-card flat bordered class="summary-card"><q-card-section><div class="summary-label">{{ item.label }}</div><div class="summary-value">{{ item.value }}</div></q-card-section></q-card></div></div>
        <q-banner rounded class="notice q-mb-lg">Registra un motivo para cada diferencia. El motivo OTRO requiere observación.</q-banner>
        <q-table flat bordered :rows="diferencias" :columns="columns" row-key="idDetalle" :loading="loading" :pagination="tablePagination" :rows-per-page-options="[10, 20, 50]">
          <template #body-cell-producto="p"><q-td :props="p"><b>{{ p.row.producto }}</b><div class="muted">{{ p.row.codigoProducto }}</div></q-td></template>
          <template #body-cell-diferencia="p"><q-td :props="p"><q-badge :color="p.row.diferencia < 0 ? 'red-6' : 'blue-6'" :label="formatearDiferencia(p.row.diferencia)"/></q-td></template>
          <template #body-cell-motivo="p"><q-td :props="p"><q-select v-model="p.row.motivo" dense outlined emit-value map-options :options="motivos" label="Motivo" style="min-width:210px"/><q-input v-if="esOtro(p.row.motivo)" v-model="p.row.observacion" dense outlined autogrow maxlength="500" counter label="Observación obligatoria" class="q-mt-sm"/></q-td></template>
          <template #no-data><div class="full-width text-center q-pa-xl text-grey-6">No hay diferencias registradas.</div></template>
        </q-table>
      </q-card-section>
      <q-card-actions class="actions"><q-btn flat no-caps color="negative" icon="cancel" label="Cancelar inventario" :disable="loading || saving" @click="abrirCancelacion"/><q-space/><q-btn unelevated no-caps color="green-8" icon="verified" label="Aprobar y generar ajuste" :loading="saving" :disable="loading" @click="aprobar"/></q-card-actions>
    </q-card>
    <q-dialog v-model="cancelDialog" persistent><q-card class="cancel-card"><div class="cancel-bar"></div><div class="cancel-header"><div class="cancel-icon"><q-icon name="cancel" size="24px"/></div><div class="col"><div class="cancel-title">Cancelar inventario</div><div class="cancel-sub">Esta acción cambiará el estado a CANCELADO</div></div><q-btn flat round dense icon="close" @click="cancelDialog=false"/></div><q-card-section class="cancel-body"><div class="cancel-target"><q-icon name="inventory_2" color="orange-8" size="22px"/><div><b>{{ inventario?.codigo }}</b><span>Inventario físico</span></div></div><q-banner rounded class="cancel-warning"><template #avatar><q-icon name="warning_amber" color="orange-8"/></template>El inventario cancelado no podrá continuar, aprobarse ni generar ajustes en Kardex.</q-banner><q-input v-model="motivoCancelacion" outlined type="textarea" autogrow maxlength="500" counter label="Motivo de cancelación *" placeholder="Escribe por qué se cancela este inventario"/></q-card-section><q-card-actions class="cancel-actions"><q-btn flat no-caps label="Volver" @click="cancelDialog=false"/><q-space/><q-btn unelevated no-caps color="orange-8" icon="cancel" label="Confirmar cancelación" :loading="saving" @click="cancelar"/></q-card-actions></q-card></q-dialog>
  </q-dialog>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { listarDiferenciasInventarioFisico, guardarDiferenciasInventarioFisico, aprobarInventarioFisico, cancelarInventarioFisico } from '../../api/inventarioFisico/inventarioFisico'

const props = defineProps({ modelValue: Boolean, inventario: Object })
const emit = defineEmits(['update:modelValue', 'aprobado', 'cancelado'])
const $q = useQuasar(); const diferencias = ref([]); const loading = ref(false); const saving = ref(false); const error = ref(''); const cancelDialog = ref(false); const motivoCancelacion = ref(''); const tablePagination = ref({ page: 1, rowsPerPage: 10 })
const motivos = [{ label: 'Merma o daño', value: 'MERMA_DANIO' }, { label: 'Error de registro', value: 'ERROR_REGISTRO' }, { label: 'Producto encontrado', value: 'PRODUCTO_ENCONTRADO' }, { label: 'Pérdida', value: 'PERDIDA' }, { label: 'Otro', value: 'OTRO' }]
const columns = [{ name: 'producto', label: 'Producto', field: 'producto', align: 'left' }, { name: 'cantidadSistema', label: 'Sistema', field: 'cantidadSistema', align: 'center' }, { name: 'cantidadFisica', label: 'Físico', field: 'cantidadFisica', align: 'center' }, { name: 'diferencia', label: 'Diferencia', field: 'diferencia', align: 'center' }, { name: 'motivo', label: 'Motivo', field: 'motivo', align: 'left' }]
const resumen = computed(() => [{ label: 'Diferencias', value: diferencias.value.length }, { label: 'Entradas', value: diferencias.value.filter(x => x.diferencia > 0).length }, { label: 'Salidas', value: diferencias.value.filter(x => x.diferencia < 0).length }, { label: 'Pendientes', value: diferencias.value.filter(x => !x.motivo).length }])
const esOtro = value => ['OTRO', 'OTROS'].includes(String(value || '').toUpperCase()); const formatearDiferencia = value => value == null ? '--' : `${value > 0 ? '+' : ''}${value}`; const mensajeError = (e, fallback) => e?.response?.data?.message || fallback
async function cargar() { if (!props.inventario?.id) return; loading.value = true; error.value = ''; try { const response = await listarDiferenciasInventarioFisico(props.inventario.id, { page: 0, size: 100, sortBy: 'producto', sortDir: 'asc' }); diferencias.value = (response?.content || []).map(item => ({ ...item, motivo: item.motivo || null, observacion: item.observacion || '' })) } catch (e) { error.value = mensajeError(e, 'No se pudieron cargar las diferencias.') } finally { loading.value = false } }
function validar() { const faltante = diferencias.value.find(x => !x.motivo); if (faltante) return `Selecciona el motivo de ${faltante.producto}.`; const sinObservacion = diferencias.value.find(x => esOtro(x.motivo) && !x.observacion?.trim()); return sinObservacion ? `Escribe la observación de ${sinObservacion.producto}.` : '' }
async function aprobar() { const validacion = validar(); if (validacion) return $q.notify({ type: 'warning', message: validacion }); saving.value = true; try { const detalles = diferencias.value.map(x => ({ idDetalle: x.idDetalle, motivo: x.motivo, observacion: x.observacion?.trim() || null })); if (detalles.length) await guardarDiferenciasInventarioFisico(props.inventario.id, { detalles }); await aprobarInventarioFisico(props.inventario.id); $q.notify({ type: 'positive', message: detalles.length ? 'Inventario aprobado y ajuste registrado en Kardex.' : 'Inventario aprobado sin diferencias.' }); emit('aprobado'); emit('update:modelValue', false) } catch (e) { $q.notify({ type: 'negative', message: mensajeError(e, 'No se pudo aprobar el inventario.') }) } finally { saving.value = false } }
function abrirCancelacion() { motivoCancelacion.value = ''; cancelDialog.value = true }
async function cancelar() { if (!motivoCancelacion.value.trim()) return $q.notify({ type: 'warning', message: 'El motivo de cancelación es obligatorio.' }); saving.value = true; try { await cancelarInventarioFisico(props.inventario.id, { motivo: motivoCancelacion.value.trim() }); cancelDialog.value = false; $q.notify({ type: 'positive', message: 'Inventario cancelado correctamente.' }); emit('cancelado'); emit('update:modelValue', false) } catch (e) { $q.notify({ type: 'negative', message: mensajeError(e, 'No se pudo cancelar el inventario.') }) } finally { saving.value = false } }
watch(() => [props.modelValue, props.inventario?.id], ([visible]) => { if (visible) cargar() }, { immediate: true })
</script>

<style scoped>
.review-dialog{width:min(1450px,96vw);max-width:1450px;height:min(900px,94vh);display:flex;flex-direction:column;border-radius:18px;background:#f5f7f4;font-family:'Nunito',sans-serif}.toolbar{min-height:76px;padding:0 22px;background:linear-gradient(135deg,#f1f9ec,#fff);border-bottom:1px solid #d8e5d3}.toolbar-title{font-weight:900;color:#243323}.toolbar-title span{color:#4a8c25}.content{overflow:auto;flex:1;padding:22px}.summary-card,.q-table{border-color:#dfe7dc;border-radius:15px}.summary-label,.muted{font-size:11px;color:#7b857c}.summary-value{font-size:23px;font-weight:900;color:#356d20}.notice{background:#eef8e9;color:#34572b;border:1px solid #d9ead1}.actions{padding:14px 22px;background:#fff;border-top:1px solid #dfe7dc}.q-table :deep(thead tr){background:#f0f8e9}.q-table :deep(th){font-weight:900;color:#3f5140}@media(max-width:650px){.review-dialog{width:100vw;height:100vh;max-height:100vh;border-radius:0}.content{padding:14px}.actions{flex-wrap:wrap}}
.cancel-card{width:min(520px,94vw);border-radius:20px;overflow:hidden;background:#fff;border:1px solid #f0dfc8;box-shadow:0 20px 60px rgba(123,76,21,.16);font-family:'Nunito',sans-serif}.cancel-bar{height:3px;background:linear-gradient(90deg,#82bd43,#d97b1a,#b75b0a)}.cancel-header{display:flex;align-items:flex-start;gap:12px;padding:16px 20px 14px;background:#fff8f0;border-bottom:1px solid #f5dbb8}.cancel-icon{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;color:#d97b1a;background:#fef3e2;border:1.5px solid #f5c97a}.cancel-title{font-size:17px;font-weight:900;color:#2a5c1a}.cancel-sub{font-size:11px;font-weight:600;color:#a56a22;margin-top:3px}.cancel-body{padding:18px 20px 8px}.cancel-target{display:flex;align-items:center;gap:11px;padding:12px 14px;margin-bottom:14px;border:1px solid #e4edd8;border-radius:12px;background:#f7f9f4}.cancel-target div{display:flex;flex-direction:column;gap:2px}.cancel-target b{font-size:14px;color:#2a5c1a}.cancel-target span{font-size:11px;color:#7b857c}.cancel-warning{margin-bottom:15px;background:#fff8f0;color:#a05c10;border:1px solid #f5c97a;font-size:12px;line-height:1.5}.cancel-actions{padding:14px 20px 18px;border-top:1px solid #e4edd8;background:#fff}@media(max-width:600px){.cancel-card{width:100vw;border-radius:0}.cancel-body{padding:16px 14px 8px}.cancel-actions{padding:14px}}
</style>
